<?php
include '../includes/session.php';include '../database/config.php';include '../includes/helpers.php';requireAdmin();requirePermission('records.manage');$id=(int)($_GET['id']??0);$actor=(int)$_SESSION['user_id'];$stmt=$conn->prepare('SELECT original_name FROM sacramental_import_batches WHERE import_id=? AND created_by=?');$stmt->bind_param('ii',$id,$actor);$stmt->execute();$batch=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$batch){http_response_code(404);exit('Import not found.');}$stmt=$conn->prepare("SELECT row_number,errors_json,row_data FROM sacramental_import_rows WHERE import_id=? AND validation_status<>'valid' ORDER BY row_number");$stmt->bind_param('i',$id);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="import-errors-'.$id.'.csv"');$out=fopen('php://output','wb');fputcsv($out,['row','errors','data']);foreach($rows as$r){$safe=function($v){$v=(string)$v;return preg_match('/^[=+\-@]/',ltrim($v))?"'".$v:$v;};fputcsv($out,[$r['row_number'],$safe(implode('; ',json_decode($r['errors_json'],true)?:[])),$safe($r['row_data'])]);}fclose($out);
